import re


def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("empty string")
    m = re.fullmatch(r'(?:(?:(?:(?:(\d+)d)?(\d+)h)?(\d+)m)?(\d+)s)?', s)
    if not m or m.lastindex is None or all(g is None for g in m.groups()):
        raise ValueError(f"not a valid duration: {s!r}")
    d, h, mi, sec = m.groups()
    return (int(d) * 86400 if d else 0) + (int(h) * 3600 if h else 0) + (int(mi) * 60 if mi else 0) + (int(sec) if sec else 0)
