function compareSemver(a, b) {
  const parse = (v) => {
    const [core, prerelease = ''] = String(v).split('-', 2);
    const [major, minor, patch] = core.split('.').map(Number);
    const pre = prerelease === '' ? [] : prerelease.split('.');
    return { major, minor, patch, pre };
  };

  const numCmp = (x, y) => (x === y ? 0 : (x < y ? -1 : 1));
  const A = parse(a);
  const B = parse(b);

  let c = numCmp(A.major, B.major);
  if (c) return c;
  c = numCmp(A.minor, B.minor);
  if (c) return c;
  c = numCmp(A.patch, B.patch);
  if (c) return c;

  if (A.pre.length === 0 && B.pre.length === 0) return 0;
  if (A.pre.length === 0) return 1;
  if (B.pre.length === 0) return -1;

  const len = Math.min(A.pre.length, B.pre.length);
  for (let i = 0; i < len; i++) {
    const x = A.pre[i];
    const y = B.pre[i];
    const xNum = /^\d+$/.test(x);
    const yNum = /^\d+$/.test(y);
    if (xNum && yNum) {
      c = numCmp(Number(x), Number(y));
    } else {
      c = x < y ? -1 : (x > y ? 1 : 0);
    }
    if (c) return c;
  }

  return numCmp(A.pre.length, B.pre.length);
}
